CREATE PROCEDURE "dba".verifica_objeto()BEGIN	IF EXISTS (SELECT procid			FROM sysprocedures			WHERE procname = 'u820_ce_10040_regu2materias') THEN		DROP PROCEDURE u820_ce_10040_regu2materias;	END IF;		ENDEND PROCEDURE;EXECUTE PROCEDURE "dba".verifica_objeto();DROP PROCEDURE "dba".verifica_objeto();-- Execute procedure u820_ce_10040_regu2materias("FCA", "001", "27569666-3", "10040", "04/10", 13)Create procedure "dba".u820_ce_10040_regu2materias (v_unidad_acad	like sga_alumnos.unidad_academica,				v_carrera		like sga_alumnos.carrera,				v_legajo		like sga_alumnos.legajo,				v_materia		like sga_cursadas.materia,				v_plan		like sga_alumnos.plan,				v_version		like sga_actas_examen.version)						returning smallint, varchar(255);begindefine v_resu numeric(1);define v_c_resu char(76);define n_cant_ciclo integer;define n_cant_apro integer;let v_c_resu = " ";   BEGIN      ON EXCEPTION IN (-206)        -- Tabla no existe continuo el proceso. Es por el delete de la        -- tabla temporal	      END EXCEPTION WITH RESUME;      -- Borro la tabla temporal	      DROP TABLE temp_materias_conjunto_10040;   END;-- Obtiene la cantidad de materias del Ciclo Básico Aprobadas/RegularizadasSelect  materiaFrom sga_cursadas h Where h.resultado = "A"	and h.unidad_academica = v_unidad_acad	and h.carrera = v_carrera	and h.legajo = v_legajo	and materia in ("10009","10010")Unionselect  materia	from vw_hist_academica 	where unidad_academica = v_unidad_acad	and carrera = v_carrera    and legajo =v_legajo	and resultado = "A"	and materia in  ("10009","10010")Into temp temp_materias_conjunto_10040;Select count(Distinct materia) Into n_cant_aproFrom temp_materias_conjunto_10040;-- *************************************************************************************************************************************-- U820-- Cantidad de materias regularizadas necesarios para pasar el control: se considera tener regularizada 2 materias ("10009","10010") de la carrera.-- *************************************************************************************************************************************if v_plan = "2004" then 	If n_cant_apro = 2 Then		let v_resu = 1;	else		let v_resu = -1;		let v_c_resu = "82005002";	end if;end if;if v_plan = "04/10" then 	If n_cant_apro = 2 Then		let v_resu = 1;	else		let v_resu = -2;		let v_c_resu =  "82005002";	end if;end if;return v_resu, v_c_resu;end;end procedure;-- *************** Fin del procedimiento "dba".u820_ce_10040_regu2materias  ******************-- *****************************************************************************-- Permisos del procedimiento "dba".u820_ce_10040_regu2materias -- *****************************************************************************revoke execute on "dba".u820_ce_10040_regu2materias  from public;grant execute on "dba".u820_ce_10040_regu2materias  to guarani; -- Rol de usuarios de Gestiongrant execute on "dba".u820_ce_10040_regu2materias  to internet; -- Rol de usuario de Internet